	@Test
	void numericValuesInMixedUnionRemainTermExactPrimitiveRows() {
		BindingSetAssignment numeric = values("name", INTEGER_ONE);
		Union mixed = new Union(numeric,
				new StatementPattern(Var.of("subject"), Var.of("link", LINK, true), Var.of("name")));
		SingleStatementSource source = new SingleStatementSource();
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null,
				null, 0L, new EvaluationStatistics(), false);
		LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(
				new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);
		planner.collectSyntheticValues(mixed);
		planner.valueGuardsSupported = true;

		SlotPlan compiled = planner.compileTuple(mixed, false);

		assertThat(compiled).isInstanceOf(UnionPlan.class);
		SlotPlan numericArm = ((UnionPlan) compiled).left;
		assertThat(numericArm).isInstanceOf(ValuesPlan.class);
		ValuesPlan values = (ValuesPlan) numericArm;
		assertThat(values.rows).hasSize(1);
		assertThat(values.rows[0].slots).containsExactly(planner.slot("name"));
		assertThat(values.rows[0].values).containsExactly(INTEGER_ONE_ID);
		assertThat(planner.pendingValueGuards)
				.as("RDF-term VALUES rows must not become value-equality guards")
				.isEmpty();
	}

	@Test
	void liveLookupScopeWithoutRetainedDictionarySnapshotCannotProveFiniteAbsence() throws Exception {
		Literal valueInsertedAfterProof = VF.createLiteral("live-only-value");
		LiveDictionarySource source = new LiveDictionarySource(valueInsertedAfterProof);
		BindingSetAssignment finiteValues = new BindingSetAssignment();
		finiteValues.setBindingNames(Set.of("term"));
		finiteValues.setBindingSets(List.of(new ListBindingSet(List.of("term"), valueInsertedAfterProof)));
		Join witness = new Join(patternForTerm(), finiteValues);
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null,
				null, 0L, new EvaluationStatistics(), false);
		LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(
				new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);
		assertThat(BindingSetAssignmentKeyability.canInspect(finiteValues)).isTrue();
		assertThat(LmdbNativeAggregatePlannerBase.canDiscardWithoutEvaluation(witness)).isTrue();
		assertThat(LmdbNativeAggregatePlannerBase.termSafeAbsenceProof(valueInsertedAfterProof)).isTrue();
		assertThat(LmdbCacheValueCopies.copyValueForFiniteAbsenceProof(valueInsertedAfterProof)).isNotNull();
		assertThat(source.idOf(valueInsertedAfterProof)).isEqualTo(UNKNOWN_ID);
		assertThat(source.valueLookupScope()).isNotNull().isSameAs(source.valueLookupScope());
		assertThat(planner.islandsEnabled).isTrue();

		SlotPlan absenceProof = planner.compileJoinWithAbsentFiniteValues((Join) witness);

		assertThat(absenceProof)
				.as("a stable lookup token from a live custom source does not certify retained dictionary absence")
				.isNull();

		source.insert(valueInsertedAfterProof);
		long insertedId = source.idOf(valueInsertedAfterProof);
		assertThat(insertedId).isNotEqualTo(UNKNOWN_ID);
		assertThat(source.has(UNKNOWN_ID, LINK_ID, insertedId, 0L))
				.as("the live source fixture exposes the inserted statement before compiling its row plan")
				.isTrue();
		finiteValues.setBindingSets(List.of(new ListBindingSet(List.of("term"), valueInsertedAfterProof)));
		planner.resetValuesFallbackCompilation();
		assertThat(planner.compileJoinWithAbsentFiniteValues((Join) witness))
				.as("source and AST changes followed by compiler reset must recheck the current dictionary")
				.isNull();
		planner.collectSyntheticValues(witness);
		SlotPlan patternOnly = planner.compileTuple(witness.getLeftArg(), false);
		SlotPlan valuesOnly = planner.compileTuple(finiteValues, false);
		SlotPlan executable = planner.compileTuple(witness, false);
		assertThat(executable).isNotSameAs(EmptyPlan.INSTANCE);
		assertThat(patternOnly).isInstanceOf(PatternPlan.class);
		assertThat(valuesOnly).isInstanceOf(ValuesPlan.class);
		assertThat(((ValuesPlan) valuesOnly).rows[0].values).containsExactly(insertedId);
		planner.layout.freeze(planner.slotNames);
		RowState patternRow = new RowState(source, planner.layout, EmptyBindingSet.getInstance());
		assertThat(NativeRowSeeder.seed(patternRow.slots, patternRow.layout, patternRow.base, patternRow.source))
				.isTrue();
		patternRow.recomputeBoundMask();
		try (RowCursor cursor = patternOnly.open(patternRow)) {
			boolean foundPatternRow = cursor.next();
			assertThat(foundPatternRow)
					.as("PatternPlan reads the inserted source record; statement bounds=%s, has bounds=%s",
							java.util.Arrays.toString(source.lastStatementBounds),
							java.util.Arrays.toString(source.lastHasBounds))
					.isTrue();
			assertThat(patternRow.view.getValue("term")).isEqualTo(valueInsertedAfterProof);
			assertThat(source.lastStatementBounds).containsExactly(UNKNOWN_ID, LINK_ID, UNKNOWN_ID, UNKNOWN_ID);
		}
		RowState valuesRow = new RowState(source, planner.layout, EmptyBindingSet.getInstance());
		assertThat(NativeRowSeeder.seed(valuesRow.slots, valuesRow.layout, valuesRow.base, valuesRow.source))
				.isTrue();
		valuesRow.recomputeBoundMask();
		try (RowCursor cursor = valuesOnly.open(valuesRow)) {
			assertThat(cursor.next()).as("ValuesPlan binds the inserted dictionary ID").isTrue();
			assertThat(valuesRow.view.getValue("term")).isEqualTo(valueInsertedAfterProof);
		}
		RowState row = new RowState(source, planner.layout, EmptyBindingSet.getInstance());
		assertThat(NativeRowSeeder.seed(row.slots, row.layout, row.base, row.source)).isTrue();
		row.recomputeBoundMask();
		try (RowCursor cursor = executable.open(row)) {
			assertThat(cursor.next())
					.as("the recompiled live source exposes its newly inserted value (plan=%s)",
							executable.getClass().getSimpleName())
					.isTrue();
			assertThat(row.view.getValue("term")).isEqualTo(valueInsertedAfterProof);
			assertThat(cursor.next()).isFalse();
		}
	}

	@Test
	void valuesFallbackResetDoesNotKeepAbsentProofAfterLiveSourceAndAstMutation() {
		Literal value = VF.createLiteral("live-value-after-reset");
		LiveDictionarySource source = new LiveDictionarySource(value) {
			@Override
			public boolean tryRetainDictionaryTermMembership() {
				return true;
			}
		};
		BindingSetAssignment finiteValues = new BindingSetAssignment();
		finiteValues.setBindingNames(Set.of("term"));
		finiteValues.setBindingSets(List.of(new ListBindingSet(List.of("term"), value)));
		Join witness = new Join(patternForTerm(), finiteValues);
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null,
				null, 0L, new EvaluationStatistics(), false);
		LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(
				new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);

		assertThat(planner.compileJoinWithAbsentFiniteValues(witness))
				.as("the retained source proves the original value absent")
				.isSameAs(EmptyPlan.INSTANCE);
		source.insert(value);
		finiteValues.setBindingSets(List.of(new ListBindingSet(List.of("term"), value)));
		planner.resetValuesFallbackCompilation();

		assertThat(planner.compileJoinWithAbsentFiniteValues(witness))
				.as("a reset after source and AST mutation must not reuse a cached empty proof")
				.isNull();
	}

	@Test
	void valueGuardsRequireTheirExactMandatoryOccurrence() {
		BindingSetAssignment mandatoryValues = values("term", LANGUAGE_TERM);
		TupleExpr mandatoryJoin = new Join(mandatoryValues,
				new StatementPattern(Var.of("subject"), Var.of("predicate", LINK, true), Var.of("term")));
		LmdbNativeAggregatePlanner mandatoryPlanner = guardPlanner(mandatoryJoin);
		SlotPlan mandatoryValuesPlan = mandatoryPlanner.compileTuple(mandatoryValues, false);
		assertGuardRecorded(mandatoryPlanner);
		assertThat(mandatoryValuesPlan).isInstanceOf(ValuesPlan.class);
		boolean mandatorySafe = mandatoryPlanner.valueGuardsSafeFor(mandatoryJoin);

		BindingSetAssignment unionValues = values("term", LANGUAGE_TERM);
		Var optimizerValuedTerm = Var.of("term", LANGUAGE_TERM, false, false);
		assertThat(optimizerValuedTerm.hasValue()).isTrue();
		assertThat(optimizerValuedTerm.isConstant()).isFalse();
		TupleExpr valuedPattern = new StatementPattern(Var.of("subject"), Var.of("predicate", LINK, true),
				optimizerValuedTerm);
		TupleExpr unrelatedUnboundValues = unboundValues("other");
		TupleExpr unionRoot = new Union(new Join(unionValues, valuedPattern), unrelatedUnboundValues);
		LmdbNativeAggregatePlanner unionPlanner = guardPlanner(unionRoot);
		SlotPlan unionValuesPlan = unionPlanner.compileTuple(unionValues, false);
		assertGuardRecorded(unionPlanner);
		assertThat(unionValuesPlan).isInstanceOf(ValuesPlan.class);
		boolean unionSafe = unionPlanner.valueGuardsSafeFor(unionRoot);

		BindingSetAssignment optionalValues = values("term", LANGUAGE_TERM);
		TupleExpr optionalInput = new Join(optionalValues,
				new StatementPattern(Var.of("subject"), Var.of("predicate", LINK, true),
						Var.of("term", LANGUAGE_TERM, false, false)));
		Projection projectedAlias = new Projection(optionalInput,
				new ProjectionElemList(new ProjectionElem("subject", "visible")), true);
		TupleExpr optionalRoot = new LeftJoin(new SingletonSet(), projectedAlias);
		LmdbNativeAggregatePlanner optionalPlanner = guardPlanner(optionalRoot);
		SlotPlan optionalValuesPlan = optionalPlanner.compileTuple(optionalValues, false);
		assertGuardRecorded(optionalPlanner);
		assertThat(optionalValuesPlan).isInstanceOf(ValuesPlan.class);
		boolean optionalSafe = optionalPlanner.valueGuardsSafeFor(optionalRoot);

		assertAll("value guards stay within mandatory occurrences",
				() -> assertThat(mandatorySafe)
						.as("a guard from a mandatory VALUES + pattern join is root-safe")
						.isTrue(),
				() -> assertThat(unionSafe)
						.as("a guard must not bind an unrelated accepting UNION arm")
						.isFalse(),
				() -> assertThat(optionalSafe)
						.as("a projected optional guard cannot escape its lexical occurrence")
						.isFalse());
	}

	@Test
	void valueGuardsDoNotCrossOpaqueOrEffectfulJoinSiblings() {
		BindingSetAssignment safeValues = values("term", LANGUAGE_TERM);
		TupleExpr safeRoot = new Join(safeValues,
				new StatementPattern(Var.of("subject"), Var.of("predicate", LINK, true), Var.of("term")));
		boolean mandatoryPatternSafe = guardIsSafeFor(safeRoot, safeValues);

		BindingSetAssignment tupleValues = values("term", LANGUAGE_TERM);
		TupleFunctionCall tupleFunction = tupleFunctionReadingTerm(false);
		TupleExpr tupleRoot = new Join(new Join(tupleFunction, tupleValues), patternForTerm());
		boolean tupleFunctionSafe = guardIsSafeFor(tupleRoot, tupleValues);

		BindingSetAssignment customValues = values("term", LANGUAGE_TERM);
		TupleFunctionCall customTuple = tupleFunctionReadingTerm(true);
		TupleExpr customRoot = new Join(new Join(customTuple, customValues), patternForTerm());
		boolean customTupleSafe = guardIsSafeFor(customRoot, customValues);

		BindingSetAssignment effectfulValues = values("term", LANGUAGE_TERM);
		FunctionCall random = new FunctionCall("RAND");
		Extension unrelatedEffect = new Extension(new SingletonSet(), new ExtensionElem(random, "sample"));
		TupleExpr effectfulRoot = new Join(new Join(unrelatedEffect, effectfulValues), patternForTerm());
		boolean effectfulSiblingSafe = guardIsSafeFor(effectfulRoot, effectfulValues);

		assertThat(LmdbNativeAggregateFilterCompiler.isRepeatable(random))
				.as("the unrelated extension is an effectful expression")
				.isFalse();
		assertAll("root value guards preserve mandatory sibling evaluation",
				() -> assertThat(mandatoryPatternSafe)
						.as("a pure mandatory pattern sibling permits the guard")
						.isTrue(),
				() -> assertThat(tupleFunctionSafe)
						.as("a tuple-function sibling can observe its guarded argument")
						.isFalse(),
				() -> assertThat(customTupleSafe)
						.as("an opaque tuple-function subclass remains a guarded sibling")
						.isFalse(),
				() -> assertThat(effectfulSiblingSafe)
						.as("a volatile unrelated extension must not be skipped by a root guard")
						.isFalse());
	}

	@Test
	void termProbeAbsenceProofRecursesThroughOnlyUnambiguousTripleComponents() {
		SingleStatementSource source = new SingleStatementSource();
		for (Value triple : List.of(PLAIN_TRIPLE_TERM, NESTED_TRIPLE_TERM)) {
			long id = source.idOf(triple);
			assertThat(id).as("the fixture gives this real TripleTerm a known term id").isNotEqualTo(UNKNOWN_ID);
			assertAll("a triple whose recursive components have one RDF-term spelling",
					() -> assertThat(LmdbNativeAggregatePlannerBase.termSafeAbsenceProof(triple))
							.as("the full term proves absence")
							.isTrue(),
					() -> assertThat(LmdbNativeAggregatePlannerBase.termProbeSafeId(id, triple))
							.as("a known exact term id may be used for the probe")
							.isTrue());
		}
		long languageTripleId = source.idOf(LANGUAGE_TRIPLE_TERM);
		assertThat(languageTripleId).isNotEqualTo(UNKNOWN_ID);
		assertAll("an embedded language literal retains ambiguous legacy spelling",
				() -> assertThat(LmdbNativeAggregatePlannerBase.termSafeAbsenceProof(LANGUAGE_TRIPLE_TERM)).isFalse(),
				() -> assertThat(LmdbNativeAggregatePlannerBase.termProbeSafeId(languageTripleId, LANGUAGE_TRIPLE_TERM))
						.isFalse(),
				() -> assertThat(LmdbNativeAggregatePlannerBase.termProbeSafeId(UNKNOWN_ID, PLAIN_TRIPLE_TERM))
						.isFalse());
	}

	@Test
	void nativeConditionsProjectHiddenApiBindingsIncludingImplicitExistsCorrelation() {
		List<ValueExpr> conditions = List.of(new Not(new Bound(Var.of("hidden"))),
				new Compare(Var.of("hidden"), new ValueConstant(NAME_1)), new Exists(values("hidden", NAME_2)));
		List<Boolean> expected = List.of(true, false, true);
		for (int i = 0; i < conditions.size(); i++) {
			StatementPattern pattern = new StatementPattern(Var.of("subject"), Var.of("link", LINK, true),
					Var.of("name"));
			Filter filter = new Filter(pattern, conditions.get(i));
			filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("subject", "name")));
			SingleStatementSource source = new SingleStatementSource();
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null,
					null, 0L, new EvaluationStatistics(), false);
			QueryEvaluationStep step = LmdbNativeAggregateCompiler.tryCompile(filter,
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);
			assertThat(step).as("projected scalar/EXISTS condition retains a native tuple plan").isNotNull();
			MapBindingSet api = new MapBindingSet();
			api.addBinding("hidden", NAME_1);
			try (CloseableIteration<BindingSet> rows = step.evaluate(api)) {
				assertThat(rows.hasNext()).as("condition %s", conditions.get(i)).isEqualTo(expected.get(i));
				if (expected.get(i)) {
					assertThat(rows.next().getValue("hidden")).as("condition projection does not trim output rows")
							.isEqualTo(NAME_1);
					assertThat(rows.hasNext()).isFalse();
				}
			}
		}
	}

	@Test
	void projectedSinglePatternWitnessKeepsItsNativeProbeAndHidesCallerBindings() {
		for (boolean negated : List.of(false, true)) {
			StatementPattern witness = new StatementPattern(Var.of("subject"), Var.of("link", LINK, true),
					Var.of("hidden"));
			ValueExpr condition = new Exists(witness);
			if (negated) {
				condition = new Not(condition);
			}
			Filter filter = new Filter(new SingletonSet(), condition);
			filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("subject")));
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null,
					null, 0L, new EvaluationStatistics(), false);
			LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, new SingleStatementSource());
			planner.slot("subject");
			planner.slot("hidden");
			NativeBooleanFilter predicate = planner.compileProjectedFilter(filter);
			NativeBooleanFilter probe = predicate instanceof NegatedNativeBooleanFilter not ? not.delegate : predicate;
			assertThat(probe).as("projected witness keeps the direct native existence probe")
					.isInstanceOf(StatementPatternExistsFilter.class);
			planner.layout.freeze(planner.slotNames);
			MapBindingSet api = new MapBindingSet();
			api.addBinding("subject", SUBJECT);
			api.addBinding("hidden", NAME_2);
			RowState row = new RowState(planner.source, planner.layout, api);
			row.slots[planner.slot("subject")] = SUBJECT_ID;
			row.slots[planner.slot("hidden")] = NAME_2_ID;
			row.recomputeBoundMask();
			assertThat(predicate.accept(row))
					.as("hidden caller value cannot constrain the witness, negated=%s", negated)
					.isEqualTo(!negated);
			assertThat(row.view.getValue("hidden")).as("projection applies only to the condition").isEqualTo(NAME_2);
		}
	}

	@Test
	void projectedCompoundWitnessKeepsNativeFramesAndHidesImplicitCallerCorrelation() {
		StatementPattern first = new StatementPattern(Var.of("subject"), Var.of("link", LINK, true), Var.of("hidden"));
		StatementPattern second = new StatementPattern(Var.of("subject"), Var.of("link", LINK, true), Var.of("other"));
		List<TupleExpr> witnesses = List.of(new Join(first.clone(), second.clone()),
				new Union(new Join(first.clone(), second.clone()), values("hidden", NAME_1)),
				new LeftJoin(first.clone(), second.clone()),
				new Difference(first.clone(), values("hidden", NAME_2)),
				new Join(values("hidden", NAME_1), second.clone()));
		for (TupleExpr witness : witnesses) {
			Filter filter = new Filter(new SingletonSet(), new Exists(witness));
			filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("subject")));
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null,
					null, 0L, new EvaluationStatistics(), false);
			LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, new SingleStatementSource());
			planner.slot("subject");
			planner.slot("hidden");
			planner.slot("other");
			NativeBooleanFilter predicate = planner.compileProjectedFilter(filter);
			assertThat(predicate).as("compound witness retains a native frame: %s", witness)
					.isInstanceOf(ExistsFilter.class);
			planner.layout.freeze(planner.slotNames);
			MapBindingSet api = new MapBindingSet();
			api.addBinding("subject", SUBJECT);
			api.addBinding("hidden", NAME_2);
			api.addBinding("other", NAME_2);
			RowState row = new RowState(planner.source, planner.layout, api);
			row.slots[planner.slot("subject")] = SUBJECT_ID;
			row.slots[planner.slot("hidden")] = NAME_2_ID;
			row.slots[planner.slot("other")] = NAME_2_ID;
			row.recomputeBoundMask();
			assertThat(predicate.accept(row)).as("excluded API columns remain witness-local: %s", witness).isTrue();
			assertThat(row.view.getValue("hidden")).isEqualTo(NAME_2);
			assertThat(row.view.getValue("other")).isEqualTo(NAME_2);
		}
	}

